import {icon,esc,state,save,activity,course,readCount,pct,toast,go,empty,btn,heading,progressBar} from './core.js';
import {hasContentSummary,renderContentSummary} from './review.js?v=summary-integrated-20261027';
const paragraphs=s=>String(s||'').split(/\n\s*\n/).map(p=>`<p>${esc(p)}</p>`).join('');
function teachPage(l,p){
 if(!l)return `<div class="lesson-pending">${icon('book')}<h2>กำลังเรียบเรียงบทสอนสำหรับหน้านี้</h2><p>กำลังเปลี่ยนจากคำอธิบายรวมหลายหน้าเป็นบทสอนเฉพาะแต่ละหน้า หน้านี้จะมีคำอธิบาย ตัวอย่าง และคำถามทวนความเข้าใจของตัวเอง</p></div>`;
 return `<div class="lesson-kicker"><span>${icon('spark')}บทสอน · หน้า ${p}</span><span>LEARN TO UNDERSTAND</span></div><h2 class="lesson-title">${esc(l.title)}</h2><div class="lesson-intro">${paragraphs(l.intro)}</div>${l.flow?.length?`<div class="lesson-flow" aria-label="ลำดับการทำงาน">${l.flow.map((s,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><p>${esc(s)}</p></div>`).join('')}</div>`:''}${l.sections.map((s,i)=>`<section class="teaching-section"><div class="teaching-section-label"><span>${String(i+1).padStart(2,'0')}</span><h3>${esc(s.heading)}</h3></div>${paragraphs(s.body)}</section>`).join('')}${l.formula?`<div class="lesson-formula"><small>สูตรที่ใช้ในหน้านี้</small><pre>${esc(l.formula)}</pre></div>`:''}<section class="worked-example"><span class="eyebrow">${icon('bulb')}LET’S WALK THROUGH IT</span><h3>${esc(l.example.title)}</h3><ol>${l.example.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></section><div class="lesson-takeaway">${icon('bookmark')}<div><strong>จำให้ขึ้นใจ</strong><p>${esc(l.takeaway)}</p></div></div><section class="lesson-check"><span class="eyebrow">CHECK YOUR UNDERSTANDING</span><h3>ลองตอบด้วยคำพูดของคุณเอง</h3><p>${esc(l.check.question)}</p><details><summary>คิดคำตอบแล้ว · ดูคำอธิบาย ${icon('down')}</summary><div>${paragraphs(l.check.answer)}</div></details></section>`;
}
export function renderLearn(id,num,tab='teach'){
 const c=course(id);if(!c)return empty('ไม่พบบทเรียน','เลือกบทเรียนจากคลังอีกครั้ง');
 const p=Math.max(1,Math.min(c.pages.length,Math.trunc(num))),page=c.pages[p-1],k=id+':'+p,l=page.lesson;
 state.resume[id]=p;state.lastCourse=id;save();const marked=state.bookmarks.includes(k),read=(state.read[id]||[]).includes(p);
 const aside=tab==='notes'?`<label class="note-label" for="page-note">โน้ตส่วนตัว · หน้า ${p}</label><textarea id="page-note" data-key="${k}" rows="13" placeholder="ลองอธิบายสิ่งที่เพิ่งเรียน ด้วยภาษาของตัวเอง…">${esc(state.notes[k]||'')}</textarea><div class="note-saved" id="note-status">${icon('check')}บันทึกอัตโนมัติ</div><div class="notice">จดสิ่งที่ยังสงสัย หรือลองคำนวณตัวอย่างเอง แล้วกลับมาเรียนต่อได้ทุกเมื่อ</div>`:`<div class="lesson-path-header"><span>เส้นทางการเรียน</span><small>${readCount(c)}/${c.pages.length} หน้า</small></div>${progressBar(pct(c))}<div class="lesson-path">${c.pages.map(s=>`<a class="lesson-path-item ${s.number===p?'current':''} ${(state.read[id]||[]).includes(s.number)?'finished':''}" href="#learn/${id}/${s.number}" aria-current="${s.number===p?'page':'false'}"><span class="path-number">${(state.read[id]||[]).includes(s.number)?icon('check'):String(s.number).padStart(2,'0')}</span><span>${esc(s.lesson?.title||s.title)}</span></a>`).join('')}</div>`;
 return `<a href="#folder/itds-211" class="back-link">${icon('back')}กลับโฟลเดอร์รายวิชา</a><div class="reader-heading"><div><span class="eyebrow" style="margin-bottom:8px">${c.n===0?'BEFORE YOU BEGIN':'CHAPTER '+String(c.n).padStart(2,'0')} · ITDS-211</span><h1>${esc(c.title)}</h1><p>${esc(c.thai)} · เรียนตามลำดับหน้าของเอกสาร</p></div><div class="inline-actions"><a class="button small ghost" href="#summary/${id}">${icon('note')}สรุปเนื้อหา</a>${c.questions.length?`<a class="button primary small" href="#quiz/${id}">${icon('quiz')}ทำแบบทดสอบ</a>`:''}</div></div><div class="teaching-grid"><section class="teaching-main"><div class="lesson-controls"><select id="page-select" aria-label="เลือกหน้าบทเรียน">${c.pages.map(s=>`<option value="${s.number}" ${s.number===p?'selected':''}>หน้า ${s.number} · ${esc((s.lesson?.title||s.title).slice(0,64))}</option>`).join('')}</select><div class="inline-actions"><span class="lesson-page-counter">${p}<small> / ${c.pages.length}</small></span><button class="icon-button ${marked?'selected':''}" data-bookmark="${k}" aria-label="${marked?'เลิกปักหมุด':'ปักหมุดหน้านี้'}" aria-pressed="${marked}">${icon('bookmark')}</button></div></div><article class="lesson-article">${teachPage(l,p)}</article><div class="reader-next teaching-next">${btn(icon(read?'check':'book')+(read?'เรียนหน้านี้แล้ว':'บันทึกว่าเรียนแล้ว'),`data-read="${k}"`,'small ghost')}${l?btn((p===c.pages.length?'เรียนครบแล้ว ดูสรุป':'เข้าใจแล้ว เรียนหน้าถัดไป')+icon('arrow'),`data-read-next="${k}"`,'primary small'):''}</div><div class="lesson-pagination">${btn(icon('back')+'หน้าก่อนหน้า',`data-page="${p-1}" ${p===1?'disabled':''}`,'small ghost')}<span>อ้างอิงลำดับเอกสารหน้า ${p}</span>${btn('หน้าถัดไป'+icon('arrow'),`data-page="${p+1}" ${p===c.pages.length?'disabled':''}`,'small ghost')}</div></section><aside class="panel lesson-sidebar"><div class="tabs" role="tablist" aria-label="เครื่องมือบทเรียน">${[['teach','เนื้อหาในบท'],['notes','โน้ตของฉัน']].map(([v,t])=>`<button class="tab ${(tab||'teach')===v?'active':''}" role="tab" aria-selected="${(tab||'teach')===v}" data-tab="${v}">${t}</button>`).join('')}</div><div class="tab-content" role="tabpanel">${aside}</div><div class="lesson-sidebar-foot">${icon('shield')}บทสอนเรียบเรียงใหม่ตามหัวข้อแต่ละหน้า</div></aside></div>`;
}
export function afterLearn(){const current=document.querySelector('.lesson-path-item.current'),list=document.querySelector('.lesson-path');if(current&&list)list.scrollTop=Math.max(0,current.offsetTop-list.offsetTop-list.clientHeight/3);}
export function renderSummary(id){
 const c=course(id);if(!c)return empty('ไม่พบบทเรียน','เลือกบทเรียนจากคลังอีกครั้ง');const prepared=c.pages.filter(p=>p.lesson);
 const topics=`<div class="summary-grid">${c.topics.map((t,i)=>`<article class="summary-card"><span class="number">${String(i+1).padStart(2,'0')} / KEY CONCEPT</span><h3>${esc(t.title)}</h3><p>${esc(t.explain)}</p><div class="remember">${icon('bulb')}<p>${esc(t.remember)}</p></div><a class="source-link" href="#learn/${id}/${t.from}">เรียนทบทวนหน้า ${t.from} ${icon('arrow')}</a></article>`).join('')}</div>`;
 const pages=`<section class="panel section-gap"><div class="section-heading"><h2>สรุปตามหน้าสไลด์</h2><small class="muted">${prepared.length} หน้า</small></div><div class="page-summaries">${prepared.map(p=>`<details><summary><span class="pill">${p.number}</span>${esc(p.lesson.title)}${icon('down')}</summary><div><p>${esc(p.lesson.takeaway)}</p><a class="text-link" href="#learn/${id}/${p.number}">กลับไปเรียนหน้านี้ ${icon('arrow')}</a></div></details>`).join('')}</div></section>`;
 const enhanced=hasContentSummary(id);
 return `<a class="back-link" href="#learn/${id}/${state.resume[id]||1}">${icon('back')}กลับไปเรียน</a>`+(enhanced?renderContentSummary(id,{inlinePages:true}):heading('สรุปเนื้อหา · '+c.title,'สาระสำคัญของแต่ละหน้าและภาพรวมของบท'))+(enhanced?`<details class="summary-page-details" id="summary-pages-${id}"><summary><span>${icon('file')}สรุปตามหน้าสไลด์และหัวข้อเดิม</span><small>${prepared.length} หน้า</small>${icon('down')}</summary><div>${topics}${pages}</div></details>`:topics+pages)+`<div class="summary-actions"><a class="button ghost" href="#learn/${id}/${state.resume[id]||1}">${icon('back')}กลับไปเรียนต่อ</a>${c.questions.length?`<a class="button primary" href="#quiz/${id}">${icon('quiz')}เช็กความเข้าใจ · 15 ข้อ ${icon('arrow')}</a>`:''}</div>`;
}
document.addEventListener('change',e=>{if(e.target.id==='page-select'){const id=location.hash.split('/')[1];go(`#learn/${id}/${e.target.value}`);}});
document.addEventListener('input',e=>{if(e.target.id==='page-note'){state.notes[e.target.dataset.key]=e.target.value;save();const s=document.getElementById('note-status');if(s)s.innerHTML=icon('check')+'บันทึกแล้ว';}});
function markRead(k){const [id,ps]=k.split(':'),p=Number(ps);state.read[id]??=[];if(!state.read[id].includes(p)){state.read[id].push(p);activity().slides++;}save();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const id=location.hash.split('/')[1];if(b.dataset.page)go(`#learn/${id}/${b.dataset.page}`);if(b.dataset.bookmark){const k=b.dataset.bookmark;state.bookmarks=state.bookmarks.includes(k)?state.bookmarks.filter(x=>x!==k):[...state.bookmarks,k];save();go(location.hash);toast(state.bookmarks.includes(k)?'ปักหมุดหน้านี้แล้ว':'เลิกปักหมุดแล้ว');}if(b.dataset.read){markRead(b.dataset.read);go(location.hash);toast('บันทึกการเรียนแล้ว');}if(b.dataset.readNext){const [cid,p]=b.dataset.readNext.split(':');markRead(b.dataset.readNext);const c=course(cid);go(Number(p)>=c.pages.length?`#summary/${cid}`:`#learn/${cid}/${Number(p)+1}`);}});
document.addEventListener('keydown',e=>{if(!location.hash.startsWith('#learn/')||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||document.querySelector('.modal'))return;const [id,ps]=location.hash.slice(1).split('?')[0].split('/').slice(1);const c=course(id),p=Number(ps)||1;if(e.key==='ArrowRight'&&p<c.pages.length){e.preventDefault();go(`#learn/${id}/${p+1}`);}if(e.key==='ArrowLeft'&&p>1){e.preventDefault();go(`#learn/${id}/${p-1}`);}});
